export function evaluate({inputs,time}){
const g=9.8,u=inputs.launchSpeed;
const T=u/g;
const t=Math.max(0,Math.min(time,2*T));
const v=u-g*t;
const h=u*t-g*t*t/2;
const H=u*u/(2*g);
const eps=0.004;
const st=Math.abs(v)<0.02?'Still for an instant':(v>0?'Moving up':'Moving down');
const base=360,top=60;
const sc=(base-top-30)/1.4;
const y=base-h*sc;
const x=300;
const o=[];
o.push(...sdk.panel({id:'lane.toss',x:20,y:40,w:600,h:360,title:'Tossed ball',state:'Height scale fixed'}));
o.push(sdk.axis('axis.h',{x:120,y:base,length:280,orientation:'y',min:0,max:1.4,ticks:[0,0.4,0.8,1.2],label:'Height',unit:'m'}));
o.push(sdk.line('guide.launch',150,base,450,base,{role:'neutral'}));
o.push(sdk.circle('ball.toss',x,y-15,30,{role:'observed'}));
o.push(...sdk.vector('vec.v',{x:x+40,y:y-15},{value:v,direction:'up'},{scale:22,label:'v',role:'input'}));
o.push(...sdk.vector('vec.a',{x:x-40,y:y-15},{value:-g,direction:'up'},{scale:6,label:'a',role:'warning',minLength:12}));
o.push(...sdk.callout(x+110,y-40,[st,'Gravity pulls down'],{id:'callout.toss'}));
return {frame:{width:640,height:420,objects:o,readouts:[{id:'motionState',value:st},{id:'gravityState',value:'Gravity pulls down'}]},quantities:{launchSpeed:u,gravity:g,apexTime:T,apexHeight:H,velocity:v,height:h}};
}
